head.b:skin:
/* -------------------------------------------------------------------------
   Blogin 365 AI Holdings - World-Class FinTech TDS Theme (v9.0 Apex)
   Toss Design System (TDS) Deep Matte Navy & Single-Column 880px Canvas
   ------------------------------------------------------------------------- */

:root {
  --apex-bg-base: #0a0e17;
  --apex-bg-surface: #111827;
  --apex-bg-card: #131c2e;
  --apex-bg-card-hover: #19243b;
  --apex-border-card: #1f2d47;
  --apex-border-subtle: #2d3e5e;

  --apex-text-primary: #f8fafc;
  --apex-text-secondary: #94a3b8;
  --apex-text-muted: #94a3b8;

  --apex-accent-blue: #3b82f6;
  --apex-accent-blue-hover: #2563eb;
  --apex-accent-green: #10b981;
  --apex-accent-green-bg: rgba(16, 185, 129, 0.12);
  --apex-accent-red: #ef4444;

  --apex-font-sans: 'Pretendard Variable', -apple-system, BlinkMacSystemFont, system-ui, Roboto, sans-serif;
  --apex-font-mono: 'JetBrains Mono', monospace;

  --apex-radius-lg: 20px;
  --apex-radius-md: 14px;
  --apex-radius-sm: 8px;
  --apex-content-width: 880px;
}

/* CSS Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--apex-bg-base);
  color: var(--apex-text-primary);
  font-family: var(--apex-font-sans);
  font-size: 16px;
  line-height: 1.7;
  letter-spacing: -0.022em;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: var(--apex-accent-blue);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: #60a5fa;
}

/* -------------------------------------------------------------------------
   Zero-Blogger-Footprint (Blogger 기본 쓰레기 위젯 영구 박멸)
   ------------------------------------------------------------------------- */
#navbar, .Navbar, .quickedit, .widget.Attribution, .widget.Profile,
.widget.BlogArchive, .widget.Followers, .widget.Feed, .post-feeds,
.feed-links, .post-footer, .blog-feeds, .home-link, .feed-links,
.blogin-validator-hidden {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  width: 0 !important;
  opacity: 0 !important;
}

/* -------------------------------------------------------------------------
   Glassmorphism Sticky Global Header
   ------------------------------------------------------------------------- */
.apex-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  background: rgba(10, 14, 23, 0.82);
  border-bottom: 1px solid var(--apex-border-card);
  width: 100%;
}

.apex-header-inner {
  max-width: 960px;
  margin: 0 auto;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.apex-brand-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
}

.apex-brand-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 17px;
  font-weight: 800;
  color: var(--apex-text-primary);
  letter-spacing: -0.03em;
}

.apex-brand-logo svg {
  width: 22px;
  height: 22px;
  fill: var(--apex-accent-blue);
}

.apex-brand-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 6px;
  background: var(--apex-accent-green-bg);
  border: 1px solid rgba(16, 185, 129, 0.25);
  color: var(--apex-accent-green);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.apex-fx-ticker {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(17, 24, 39, 0.7);
  border: 1px solid var(--apex-border-card);
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 13px;
  font-family: var(--apex-font-mono);
  color: var(--apex-text-secondary);
}

.apex-fx-ticker .pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--apex-accent-green);
  box-shadow: 0 0 8px var(--apex-accent-green);
  animation: apexPulse 2s infinite;
}

@keyframes apexPulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.85); }
}

/* 4대 권위 필라 GNB 네비게이션 & 카테고리 알약 바 */
.apex-nav-links {
  display: flex;
  align-items: center;
  gap: 16px;
}
.apex-nav-links a {
  font-size: 13px;
  font-weight: 700;
  color: var(--apex-text-secondary);
  text-decoration: none;
  transition: color 0.15s ease;
}
.apex-nav-links a:hover {
  color: var(--apex-accent-blue);
}
@media (max-width: 960px) {
  .apex-nav-links {
    display: none;
  }
}

.apex-category-bar-wrap {
  background: rgba(15, 23, 42, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--apex-border-header);
  position: sticky;
  top: 65px;
  z-index: 99;
}
.apex-category-bar-inner {
  max-width: var(--apex-content-width);
  margin: 0 auto;
  padding: 10px 20px;
  display: flex;
  align-items: center;
  gap: 10px;
  overflow-x: auto;
  white-space: nowrap;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.apex-category-bar-inner::-webkit-scrollbar {
  display: none;
}
.apex-cat-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 700;
  color: var(--apex-text-secondary);
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid var(--apex-border-card);
  border-radius: 9999px;
  text-decoration: none;
  transition: all 0.15s ease;
  flex-shrink: 0;
}
.apex-cat-pill:hover {
  background: var(--apex-accent-blue);
  color: #ffffff;
  border-color: var(--apex-accent-blue);
}
.apex-cat-pill.vibe-special {
  background: linear-gradient(135deg, rgba(37,99,235,0.3), rgba(59,130,246,0.15));
  border-color: rgba(59,130,246,0.4);
  color: #60a5fa;
}
.apex-cat-pill.vibe-special:hover {
  background: #2563eb;
  color: #ffffff;
}

/* -------------------------------------------------------------------------
   Main 880px Canvas Wrapper
   ------------------------------------------------------------------------- */
.apex-main-wrapper {
  max-width: var(--apex-content-width);
  width: 100%;
  margin: 32px auto 60px auto;
  padding: 0 20px;
  flex: 1;
}

.apex-card {
  background: var(--apex-bg-surface);
  border: 1px solid var(--apex-border-card);
  border-radius: var(--apex-radius-lg);
  padding: 36px 32px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
}

/* Post Typography & Layout */
.apex-post-title {
  font-size: 28px;
  font-weight: 900;
  line-height: 1.35;
  color: var(--apex-text-primary);
  letter-spacing: -0.035em;
  margin-bottom: 20px;
  word-break: keep-all;
}

.apex-post-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 13px;
  color: var(--apex-text-muted);
  margin-bottom: 24px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--apex-border-card);
}

.apex-post-meta a {
  color: var(--apex-accent-blue);
  background: rgba(59, 130, 246, 0.08);
  padding: 2px 8px;
  border-radius: 4px;
}

.entry-content {
  color: var(--apex-text-primary);
  line-height: 1.8;
  font-size: 16px;
}

.entry-content h2 {
  font-size: 22px;
  font-weight: 800;
  color: var(--apex-text-primary);
  margin: 44px 0 18px 0;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--apex-border-card);
  letter-spacing: -0.025em;
}

.entry-content h3 {
  font-size: 18px;
  font-weight: 700;
  color: #e2e8f0;
  margin: 28px 0 14px 0;
}

.entry-content p {
  margin-bottom: 18px;
  color: #cbd5e1;
  word-break: keep-all;
}

.entry-content ul, .entry-content ol {
  margin: 16px 0 20px 24px;
  color: #cbd5e1;
}

.entry-content li {
  margin-bottom: 8px;
}

/* -------------------------------------------------------------------------
   WCAG 2.1 AAA Contrast & Dark Theme Isolation Shield
   (화이트 컨테이너 침범 및 텍스트 투명화 원천 차단 방어막)
   ------------------------------------------------------------------------- */
.post-body, .entry-content, .blog-post-container, article, .post {
  background-color: var(--apex-bg-base) !important;
  color: var(--apex-text-primary) !important;
}

.entry-content .blog-post-container,
.entry-content .blogin-saas-container {
  background-color: transparent !important;
  color: var(--apex-text-primary) !important;
}

.entry-content p,
.entry-content li,
.blog-post-container p,
.blog-post-container li,
.blogin-saas-container p,
.blogin-saas-container li {
  color: #e2e8f0 !important;
  line-height: 1.8;
}

.entry-content h1, .entry-content h2, .entry-content h3, .entry-content h4,
.blog-post-container h1, .blog-post-container h2, .blog-post-container h3, .blog-post-container h4,
.blogin-saas-container h1, .blogin-saas-container h2, .blogin-saas-container h3, .blogin-saas-container h4 {
  color: #ffffff !important;
}

.entry-content strong, .blog-post-container strong, .blogin-saas-container strong {
  color: #ffffff !important;
}

/* Any white container mistakenly injected gets forced to dark surface */
div[style*="background-color: #fff"],
div[style*="background-color:#fff"],
div[style*="background: #fff"],
div[style*="background:#fff"],
div[style*="background-color: white"],
div[style*="background: white"],
div[style*="background-color: rgb(255, 255, 255)"],
section[style*="background-color: #fff"],
section[style*="background: #fff"] {
  background-color: var(--apex-bg-surface) !important;
  color: var(--apex-text-primary) !important;
  border-color: var(--apex-border-card) !important;
}

/* Index List Cards (Homepage / Search) */
.apex-index-grid {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.apex-index-item {
  background: var(--apex-bg-surface);
  border: 1px solid var(--apex-border-card);
  border-radius: var(--apex-radius-md);
  padding: 24px;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.apex-index-item:hover {
  border-color: var(--apex-accent-blue);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.apex-index-title {
  font-size: 20px;
  font-weight: 800;
  margin-bottom: 10px;
  line-height: 1.4;
  letter-spacing: -0.025em;
}

.apex-index-title a {
  color: var(--apex-text-primary);
}

.apex-index-title a:hover {
  color: var(--apex-accent-blue);
}

.apex-index-snippet {
  font-size: 14px;
  color: var(--apex-text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.apex-index-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: var(--apex-text-muted);
}

.apex-btn-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  color: var(--apex-accent-blue);
  font-size: 13px;
}

/* Pagination */
.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 36px;
  padding-top: 24px;
  border-top: 1px solid var(--apex-border-card);
}

.blog-pager a {
  background: var(--apex-bg-surface);
  border: 1px solid var(--apex-border-card);
  padding: 10px 18px;
  border-radius: var(--apex-radius-sm);
  color: var(--apex-text-primary);
  font-weight: 600;
  font-size: 14px;
}

.blog-pager a:hover {
  border-color: var(--apex-accent-blue);
  background: var(--apex-bg-card-hover);
}

/* -------------------------------------------------------------------------
   Institutional Footer
   ------------------------------------------------------------------------- */
.apex-footer {
  background: #070a10;
  border-top: 1px solid var(--apex-border-card);
  padding: 44px 20px;
  margin-top: auto;
}

.apex-footer-inner {
  max-width: 960px;
  margin: 0 auto;
  text-align: center;
}

.apex-footer-brand {
  font-size: 16px;
  font-weight: 800;
  color: var(--apex-text-primary);
  margin-bottom: 8px;
}

.apex-footer-disclaimer {
  font-size: 12px;
  color: var(--apex-text-muted);
  max-width: 760px;
  margin: 0 auto 16px auto;
  line-height: 1.7;
  word-break: keep-all;
}

.apex-footer-copy {
  font-size: 12px;
  color: #475569;
}

/* -------------------------------------------------------------------------
   Mobile 360px~768px Strict Zero-Blowout Responsiveness
   ------------------------------------------------------------------------- */
@media (max-width: 768px) {
  .apex-header-inner {
    padding: 12px 16px;
  }

  .apex-fx-ticker {
    display: none; /* Hide ticker on small mobile to preserve logo space */
  }

  .apex-main-wrapper {
    margin: 16px auto 40px auto;
    padding: 0 12px;
  }

  .apex-card {
    padding: 22px 16px;
    border-radius: var(--apex-radius-md);
  }

  .apex-post-title {
    font-size: 22px;
  }

  .entry-content {
    font-size: 15px;
  }

  .entry-content h2 {
    font-size: 19px;
    margin: 32px 0 14px 0;
  }
}

body.script:
/*  */
(function() {
  try {
    var fxEl = document.getElementById('apexLiveFxTicker');
    if (fxEl && window.fetch) {
      fetch('https://open.er-api.com/v6/latest/USD')
        .then(function(r) { return r.json(); })
        .then(function(d) {
          if (d && d.rates && d.rates.KRW) {
            var rate = Math.round(d.rates.KRW * 10) / 10;
            var spanText = fxEl.querySelector('span:last-child');
            if (spanText) {
              spanText.textContent = 'USD/KRW ' + rate.toLocaleString('ko-KR') + '원 (Live)';
            }
          }
        })
        .catch(function(e) { /* Silent fallback */ });
    }
  } catch (err) {}
})();
/*  */
